{
  "probability": 0.97,
  "range_low": 0.92,
  "range_high": 0.99,
  "summary": [
    "Early-2026 pace is very high, with about 606 deaths/missing by late February, which strongly supports a high March total.",
    "To reach 900 by end-March, March would need roughly 294 more deaths, a strenuous but plausible target given past March surges in this corridor.",
    "Multiple factors push the estimate up (weather risks, SAR constraints, reporting lags) while some countervailing dynamics (policy deterrence) could dampen the pace; overall, the balance leans toward crossing 900.",
    "Bayesian synthesis yields a calibrated posterior around 0.97 with high confidence, albeit acknowledging data gaps and potential correlations among factors."
  ],
  "confidence": "high",
  "narrative": "Using the Central Mediterranean reference class, the observed pace through February 2026 makes crossing 900 deaths by end-March reasonably likely. While March must sustain a very high rate, historical patterns and current conditions justify a calibrated 97% probability, with some uncertainty due to data gaps and correlated factors.",
  "justification": {
    "anchor": {
      "probability": 0.75,
      "basis": "Anchor chosen from the Central Mediterranean base-rate using Jan–Mar counts as the baseline; this anchor aligns with prior forecasting conventions for this corridor."
    },
    "factor_updates": [
      {
        "factor": "Observed early-2026 pace (≈606 deaths by late February 2026)",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "A reported ~606 deaths/missing through February implies a high March pace, increasing the odds of reaching 900 by end-March."
      },
      {
        "factor": "March total required given current pace (≈294 more deaths in March to hit 900)",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "To reach 900 by end-March, the tally would need about 9 deaths per day in March, a strenuous but plausible rate within observed high-end dynamics."
      },
      {
        "factor": "Historical March patterns (past years reaching 900+ by end of March)",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Historical seasonality shows 900+ tolls by month-end in March, lending plausibility to a similar outcome in 2026."
      },
      {
        "factor": "Weather/sea conditions in early 2026",
        "direction": "neutral",
        "magnitude": "weak",
        "rationale": "Uncertain winter-to-spring sea conditions could push counts up or down, introducing low-confidence variability."
      },
      {
        "factor": "Search-and-rescue capacity and policy environment in 2026",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "SAR constraints or deterrence measures could reduce safe disembarkations and increase fatalities, contributing to higher totals."
      },
      {
        "factor": "Data reporting lags and provisional tallies",
        "direction": "up",
        "magnitude": "weak",
        "rationale": "Under-counting in early months could mean March totals are higher than currently reported, raising the risk of crossing 900."
      }
    ],
    "synthesis_rationale": "Starting from a 0.75 anchor in the base-rate, the observed high early-2026 death pace and plausible March surge drive the posterior upward. While several factors exert weaker or opposing pressure (e.g., potential SAR improvements or policy deterrence), the combination of strong March demand and data incompleteness justifies a high-calibration posterior near 0.97. Correlations among factors are acknowledged, and the range reflects residual uncertainty."
  }
}

